section.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/graphql-api-design.json",
  "type": "object",
  "title": "GraphQL design decision record",
  "required": [
    "schema_file",
    "pagination_style",
    "auth_strategy",
    "limits"
  ],
  "additionalProperties": false,
  "properties": {
    "schema_file": {
      "type": "string",
      "minLength": 1
    },
    "pagination_style": {
      "enum": [
        "relay_cursor",
        "offset_forbidden"
      ]
    },
    "auth_strategy": {
      "enum": [
        "permission_classes",
        "directives"
      ]
    },
    "limits": {
      "type": "object",
      "required": [
        "max_depth",
        "max_complexity"
      ],
      "properties": {
        "max_depth": {
          "type": "integer",
          "minimum": 4,
          "maximum": 12
        },
        "max_complexity": {
          "type": "integer",
          "minimum": 50,
          "maximum": 1000
        }
      }
    },
    "dataloader_per_request": {
      "type": "boolean",
      "const": true
    },
    "payload_types_present": {
      "type": "boolean",
      "const": true,
      "description": "Every mutation returns a <Name>Payload (rule mutation-error-union)."
    },
    "non_payload_mutations": {
      "type": "integer",
      "minimum": 0,
      "maximum": 0,
      "description": "Mutations returning a scalar instead of a payload (rule mutation-error-union)."
    },
    "user_errors_array_present": {
      "type": "boolean",
      "const": true,
      "description": "Payloads carry userErrors[] (rule user-errors-array)."
    },
    "scalar_id_relations": {
      "type": "integer",
      "minimum": 0,
      "maximum": 0,
      "description": "Relations exposing a raw int/uuid instead of an opaque ID (rule opaque-ids-for-relations)."
    },
    "naming_deviations": {
      "type": "integer",
      "minimum": 0,
      "maximum": 0,
      "description": "Types breaking the Connection/Input/Payload conventions (rule naming-conventions-enforced)."
    }
  }
}
